using System; using System.Collections.Generic; using System.IO; using System.Linq; using System.Runtime.Serialization.Json; using System.Security.Cryptography; using System.Text;
namespace EngiSentry.Intelligence { public static class JevSemanticAssistPayloadBuilder { public static JevSystemOneRequest Build(IReadOnlyList<SemanticAmbiguityCase> cases) { var r=new JevSystemOneRequest(); foreach(var c in cases.OrderBy(x=>x.EvidenceId,StringComparer.Ordinal)) { r.State.Add(c.EvidenceId,Sanitize(c)); r.Questions.Add(c.EvidenceId,new JevChoiceQuestion { Instructions="Classify `"+c.EvidenceId+"` as exactly one provided semantic role. This is an advisory semantic classification only; do not infer engineering requirements, distances, standards, or authority.", Criteria=Criteria() }); } return r; } public static string ComputeSha256(SemanticAmbiguityCase c) { using(var s=new MemoryStream()){new DataContractJsonSerializer(typeof(SemanticAmbiguityCase)).WriteObject(s,Sanitize(c)); using(SHA256 h=SHA256.Create()) return BitConverter.ToString(h.ComputeHash(s.ToArray())).Replace("-",string.Empty);}} private static Dictionary<string,string> Criteria()=>new Dictionary<string,string>(StringComparer.Ordinal){{JevSemanticLabels.AccessRoadEdge,"Access-road edge relevant to clearance measurement."},{JevSemanticLabels.SecurityFence,"Plant or security fence relevant to clearance measurement."},{JevSemanticLabels.UnitBoundary,"Unit boundary."},{JevSemanticLabels.Unrelated,"Another semantic purpose."},{JevSemanticLabels.Unknown,"Insufficient evidence."}}; private static SemanticAmbiguityCase Sanitize(SemanticAmbiguityCase c)=>new SemanticAmbiguityCase { EvidenceId=Clean(c.EvidenceId,80), GeometryKind=Clean(c.GeometryKind,48), LayerName=Blank(Clean(c.LayerName,80)), CurrentDeterministicState="Ambiguous", ExistingCandidateKinds=(c.ExistingCandidateKinds??new List<string>()).Where(JevSemanticLabels.All.Contains).OrderBy(x=>x,StringComparer.Ordinal).ToList(), NearbyTextFragments=(c.NearbyTextFragments??new List<string>()).Select(x=>Clean(x,120)).Where(x=>x.Length>0).OrderBy(x=>x,StringComparer.Ordinal).Take(3).ToList(), SpatialContext=(c.SpatialContext??new List<string>()).Select(x=>Clean(x,80)).Where(x=>x.Length>0).OrderBy(x=>x,StringComparer.Ordinal).Take(4).ToList(), MeasurementBasisHints=(c.MeasurementBasisHints??new List<string>()).Select(x=>Clean(x,48)).Where(x=>x.Length>0).OrderBy(x=>x,StringComparer.Ordinal).Take(3).ToList() }; private static string? Blank(string x)=>x.Length==0?null:x; private static string Clean(string? x,int max){string value=x??string.Empty;if(value.Length==0)return string.Empty; var b=new StringBuilder();foreach(char c in value){if(!char.IsControl(c))b.Append(c);if(b.Length==max)break;}return b.ToString();} } }
